rows=[]
def add(id,name,h1,h2,h3,note,aliases=()):rows.append(dict(id=id,name=name,hints=[h1,h2,h3],note=note,aliases=list(aliases),source=UP,anchor=[225,270],shapes=[dict(d='M221,270a4,4 0 1,0 8,0a4,4 0 1,0 -8,0',kind='tissue')]))
add('nostril','External naris','This is an external opening of the nose.','It leads into the nasal vestibule.','Use the singular anatomical name; the plural is nares.','Each external naris opens into a vestibule. The paired external openings are the nares.',['Nostril','Anterior naris'])
add('nasal-vestibule','Nasal vestibule','Look just inside the external nose.','This anterior entrance lies before the main nasal cavity.','It is lined initially by skin and contains coarse hairs called vibrissae.','The nasal vestibule is the skin-lined anterior part of the nasal cavity. Its lining transitions toward respiratory mucosa.')
add('nasal-septum','Nasal septum','This is on the medial wall of the nasal cavity.','It separates the right and left nasal passages.','Its principal components include septal cartilage, vomer and the perpendicular plate of the ethmoid.','The septum divides the nasal cavity into right and left passages; septal deviation is common.',['Septum of nose'])
for id,name,pos,level in [('superior-concha','Superior nasal concha','uppermost','ethmoid'),('middle-concha','Middle nasal concha','middle','ethmoid'),('inferior-concha','Inferior nasal concha','lowest','separate bone')]:
 add(id,name,'Look at a curved projection on the lateral nasal wall.',f'This is the {pos} of the three principal conchae.',f'Its bony support is the {level}; include its positional name.',f'The {name.lower()} increases mucosal surface area. Its corresponding meatus lies inferior to it.',[name.replace('concha','turbinate'),name.replace('nasal ','')])
for id,name,pos,relation,note in [('superior-meatus','Superior nasal meatus','superior','below the superior nasal concha','Posterior ethmoidal air cells usually drain into the superior meatus.'),('middle-meatus','Middle nasal meatus','middle','below the middle nasal concha','The middle meatus receives frontal, maxillary and anterior/middle ethmoidal drainage through associated pathways.'),('inferior-meatus','Inferior nasal meatus','inferior','below the inferior nasal concha','The nasolacrimal duct opens into the anterior part of the inferior meatus.')]:
 add(id,name,'The pin is in a passage, not in the projecting concha.',f'It lies {relation}.',f'Use the {pos} positional name followed by nasal meatus.',note,[name.replace('nasal ','')])
add('sphenoethmoidal-recess','Sphenoethmoidal recess','This small passage is high in the posterior nasal cavity.','It lies superior and posterior to the superior nasal concha.','The sphenoidal sinus opens into it.','The sphenoethmoidal recess is distinct from the superior meatus. It receives the sphenoidal sinus opening.')
add('choana','Choana','This is the posterior exit of a nasal cavity.','It communicates with the nasopharynx.','Use the singular name; the plural is choanae.','Each choana is a posterior nasal aperture between the nasal cavity and nasopharynx.',['Posterior nasal aperture','Internal naris'])
add('frontal-sinus','Frontal sinus','This air space is above the orbit.','It is within the frontal bone.','It drains toward the middle nasal meatus through the frontal recess pathway.','The paired frontal sinuses vary greatly in size and may be asymmetric or absent.')
add('ethmoidal-cells','Ethmoidal air cells','These are small air spaces between the nasal cavity and orbit.','They occur as multiple cells in the ethmoidal labyrinth.','Anterior and middle groups drain toward the middle meatus; posterior cells drain to the superior meatus.','Ethmoidal cells are multiple cavities rather than one simple sinus chamber.',['Ethmoid air cells','Ethmoidal sinuses','Ethmoid sinuses'])
add('maxillary-sinus','Maxillary sinus','This large air space lies inferior to the orbit.','It occupies the body of the maxilla.','Its opening is high on its medial wall and drains into the middle meatus.','The maxillary sinus is related inferiorly to the posterior maxillary teeth; root relationships vary.')
add('sphenoidal-sinus','Sphenoidal sinus','Use the sagittal view behind the nasal cavity.','This air space lies within the body of the sphenoid.','It opens into the sphenoethmoidal recess.','The sphenoidal sinus lies inferior to the sella turcica; its pneumatization and septation vary.',['Sphenoid sinus'])
add('nasopharynx','Nasopharynx','This is the upper part of the pharynx.','It lies posterior to the nasal cavity and above the soft palate.','The auditory tube opens on its lateral wall.','The nasopharynx communicates with the nasal cavity through the choanae and contains the pharyngeal tonsil.')
add('oropharynx','Oropharynx','This pharyngeal compartment is behind the oral cavity.','It extends from the soft palate toward the upper border of the epiglottis.','Palatine tonsils lie in its lateral walls.','The oropharynx carries both air and swallowed material. Boundaries should be interpreted in the position of the head and tongue shown.')
add('laryngopharynx','Laryngopharynx','This is the lower pharyngeal compartment.','It lies posterior to the larynx and continues into the oesophagus.','It extends toward the lower border of the cricoid cartilage, approximately C6 in adults.','The laryngopharynx, or hypopharynx, conducts swallowed material toward the oesophagus around the laryngeal inlet.',['Hypopharynx'])
add('hard-palate','Hard palate','This is the bony roof of the oral cavity.','It separates the oral cavity from the nasal cavity above.','It is anterior to the movable soft palate.','The hard palate consists principally of the palatine processes of the maxillae and horizontal plates of the palatine bones.')
add('soft-palate','Soft palate','This is the movable posterior part of the palate.','It continues behind the hard palate.','It elevates during swallowing to help close the nasopharynx.','The muscular soft palate separates the nasopharynx from the oropharynx during swallowing.')
add('uvula','Uvula','This is a small midline projection.','It descends from the posterior free edge of the soft palate.','Its name begins with U.','The uvula is the midline projection of the soft palate; the musculus uvulae lies within it.')
add('palatine-tonsil','Palatine tonsil','This lymphoid tissue is in the lateral oropharynx.','It lies between the palatoglossal and palatopharyngeal arches.','It is the tonsil commonly removed in a tonsillectomy.','The palatine tonsil occupies the tonsillar fossa of the oropharynx.')
add('pharyngeal-tonsil','Pharyngeal tonsil','Look at lymphoid tissue in the upper pharynx.','It is on the roof and posterior wall of the nasopharynx.','When enlarged, it is commonly called an adenoid.','The pharyngeal tonsil is part of the pharyngeal lymphoid ring. Enlargement can obstruct nasal airflow.',['Adenoid'])
add('lingual-tonsil','Lingual tonsil','This lymphoid tissue lies on the tongue.','It is at the posterior part of the tongue, near the epiglottis.','Its adjective means relating to the tongue.','The lingual tonsil consists of lymphoid aggregates at the tongue base.')
add('auditory-opening','Pharyngeal opening of auditory tube','This is an opening on the lateral nasopharyngeal wall.','It leads toward the middle ear.','Its tube is also called pharyngotympanic or Eustachian.','The pharyngeal opening of the auditory tube connects the nasopharynx with the middle ear through the tube.',['Auditory tube opening','Pharyngotympanic tube opening','Eustachian tube opening'])
add('olfactory-epithelium','Olfactory epithelium','This specialised lining lies high in the nasal cavity.','It covers parts of the roof, superior concha and adjacent septum.','Its sensory neurons detect odorants.','Olfactory epithelium occupies a restricted superior region of the nasal mucosa; its exact extent varies.')
upper=rows;rows=[]
add('epiglottis','Epiglottis','This is a leaf-shaped structure above the laryngeal inlet.','It is supported by elastic cartilage.','Its stalk attaches to the internal thyroid cartilage through a ligament.','The epiglottis contributes to airway protection during swallowing, together with laryngeal elevation and closure of the folds.')
add('thyroid-cartilage','Thyroid cartilage','This is the large shield-shaped laryngeal cartilage.','Its two laminae meet anteriorly at the laryngeal prominence.','It lies superior to the cricoid cartilage.','The thyroid cartilage forms most of the anterior and lateral laryngeal framework.')
add('cricoid-cartilage','Cricoid cartilage','This cartilage is inferior to the thyroid cartilage.','It forms a complete ring, unlike the tracheal C-shaped cartilages.','Its broad lamina is posterior, like a signet ring.','The cricoid is the only complete cartilaginous ring in the airway. Its inferior border is at about C6 in adults.')
add('arytenoid-cartilage','Arytenoid cartilage','This is one of a pair of small posterior laryngeal cartilages.','It sits on the superior border of the cricoid lamina.','Its vocal and muscular processes provide attachments for the vocal ligament and intrinsic muscles.','Rotation and gliding of the arytenoids at the cricoarytenoid joints change the position of the vocal folds.')
add('corniculate-cartilage','Corniculate cartilage','This tiny paired cartilage is above an arytenoid.','It is in the posterior part of an aryepiglottic fold.','Its name means horn-shaped.','The corniculate cartilages cap the apices of the arytenoids; their overlying mucosal tubercles can be seen from above.')
add('cuneiform-cartilage','Cuneiform cartilage','Look at a small support within an aryepiglottic fold.','Its mucosal tubercle lies anterior and lateral to the corniculate tubercle.','Its name means wedge-shaped.','The cuneiform cartilages support the aryepiglottic folds. In this superior mucosal view, the pin marks the overlying tubercle.')
add('aryepiglottic-fold','Aryepiglottic fold','This fold forms a lateral margin of the laryngeal inlet.','It extends between the epiglottis and arytenoid region.','Its name combines the two structures it connects.','The aryepiglottic folds form the lateral boundaries of the laryngeal inlet and contain small supporting cartilages.')
add('vocal-fold','Vocal fold','This is the lower of the two main paired laryngeal folds.','It contains a vocal ligament and vocalis muscle.','The opening between the right and left folds is the rima glottidis.','The true vocal folds vibrate during phonation. Their anterior attachments are to the thyroid cartilage and posterior attachments are to the arytenoid vocal processes.',['True vocal fold','Vocal cord','True vocal cord'])
add('rima-glottidis','Rima glottidis','The pin is in an opening, rather than on a fold.','It is between the right and left true vocal folds and the arytenoid vocal processes.','Use the precise two-word name for this laryngeal aperture.','The rima glottidis changes shape with breathing and phonation. The glottis includes the vocal folds and their intervening aperture.')
add('vestibular-fold','Vestibular fold','This is the upper of the two main paired laryngeal folds.','It lies superior to the true vocal fold.','It is also called a false vocal fold.','The vestibular folds contribute to protective closure of the larynx and are separated from the true folds by the laryngeal ventricles.',['False vocal fold','False vocal cord','Ventricular fold'])
add('laryngeal-ventricle','Laryngeal ventricle','This is a small recess in the lateral laryngeal wall.','It lies between the vestibular and true vocal folds.','Its saccule extends superiorly.','Each laryngeal ventricle separates the vestibular fold above from the true vocal fold below.')
add('laryngeal-vestibule','Laryngeal vestibule','This is the upper compartment of the laryngeal cavity.','It extends from the inlet down to the vestibular folds.','Do not confuse it with the nasal vestibule.','The laryngeal vestibule is the portion of the laryngeal cavity above the vestibular folds.')
add('infraglottic-cavity','Infraglottic cavity','This laryngeal space lies inferior to the true vocal folds.','It continues down to the inferior border of the cricoid cartilage.','Its first prefix means below.','The infraglottic cavity continues inferiorly into the tracheal lumen.',['Subglottic cavity'])
add('trachea','Trachea','This midline airway descends into the thorax.','It extends from the inferior cricoid border to the main bronchi.','Its wall is supported by incomplete cartilaginous rings.','The trachea begins near C6 and bifurcates near the sternal angle, around T4–T5 in adults; position varies with breathing and posture.',['Windpipe'])
add('tracheal-cartilage','Tracheal cartilage','The pin is on a supporting ring of the windpipe.','This hyaline cartilage is C-shaped and open posteriorly.','The trachealis muscle spans the posterior gap.','Tracheal cartilages support airway patency while the posterior membranous wall accommodates the adjacent oesophagus.',['Tracheal ring','Tracheal cartilaginous ring'])
add('carina','Carina','This is a ridge at the bifurcation of the trachea.','It lies between the origins of the two main bronchi.','Its name means keel.','The carina is the internal ridge at the tracheal bifurcation; its position moves during respiration.',['Tracheal carina'])
for id,name,side,h2,note in [('right-main-bronchus','Right main bronchus','right','It is generally wider, shorter and more vertical than the other main bronchus.','The right main bronchus divides into branches supplying three lobes; the superior lobar branch arises above the right pulmonary artery.'),('left-main-bronchus','Left main bronchus','left','It is generally longer and more horizontal than the other main bronchus.','The left main bronchus passes inferior to the aortic arch and divides into branches supplying two lobes.')]:
 add(id,name,'Use the anterior bronchial tree: the patient’s right is at image left.',h2,f'Include the {side} side and the term main bronchus.',note,[name.replace('main','primary')])
for id,name,lobe,side in [('right-superior-lobar-bronchus','Right superior lobar bronchus','upper','right'),('right-middle-lobar-bronchus','Right middle lobar bronchus','middle','right'),('right-inferior-lobar-bronchus','Right inferior lobar bronchus','lower','right'),('left-superior-lobar-bronchus','Left superior lobar bronchus','upper','left'),('left-inferior-lobar-bronchus','Left inferior lobar bronchus','lower','left')]:
 add(id,name,'This is a lobar branch of a main bronchus.',f'It supplies the {lobe} lobe of the {side} lung.',f'Include the side, {"superior" if lobe=="upper" else "inferior" if lobe=="lower" else "middle"}, and lobar bronchus.',f'The {name.lower()} conducts air toward the segmental bronchi of its lobe.',[name.replace('superior','upper').replace('inferior','lower')])
for id,name,side,pos,extra in [('right-superior-lobe','Superior lobe of right lung','right','upper','It lies above the horizontal fissure anteriorly.'),('right-middle-lobe','Middle lobe of right lung','right','middle','It lies between the horizontal and oblique fissures.'),('right-inferior-lobe','Inferior lobe of right lung','right','lower','Much of this lobe is posterior in the intact chest.'),('left-superior-lobe','Superior lobe of left lung','left','upper','The lingula belongs to this lobe.'),('left-inferior-lobe','Inferior lobe of left lung','left','lower','It is separated from the superior lobe by the oblique fissure.')]:
 add(id,name,'This target is lung tissue, not a bronchial branch.',f'It is the {pos} lobe on the patient’s {side}.',extra,f'The {name.lower()} is a major anatomical division supplied by its lobar bronchus. {extra}',[f'{side} {pos} lung lobe',f'{side} {pos} lobe',f'{side} {"superior" if pos=="upper" else "inferior" if pos=="lower" else "middle"} lobe'])
add('right-horizontal-fissure','Horizontal fissure of right lung','This cleft belongs to the right lung.','It separates the superior and middle lobes.','Its orientation is approximately horizontal.','The right horizontal fissure separates superior from middle lobe; fissural completeness varies.',['Right horizontal fissure'])
add('right-oblique-fissure','Oblique fissure of right lung','This cleft belongs to the right lung.','It separates the inferior lobe from the superior and middle lobes.','It descends obliquely toward the anterior lung base.','The right oblique fissure separates the inferior lobe from the other two lobes.',['Right oblique fissure'])
add('left-oblique-fissure','Oblique fissure of left lung','This cleft belongs to the left lung.','It separates the superior and inferior lobes.','It is the principal fissure in the usual two-lobed left lung.','The left oblique fissure separates the two principal left lung lobes; accessory fissures can occur.',['Left oblique fissure'])
add('terminal-bronchiole','Terminal bronchiole','Use the enlarged terminal-airway view.','This is the last purely conducting airway before alveoli appear in its wall.','It leads into respiratory bronchioles.','Terminal bronchioles have no alveoli in their walls and mark the end of the conducting zone.')
add('respiratory-bronchiole','Respiratory bronchiole','Use the enlarged terminal-airway view.','Alveoli interrupt the wall of this small airway.','It is the first airway segment of the respiratory zone.','Respiratory bronchioles have both conducting and gas-exchange functions; they continue into alveolar ducts.')
add('alveolar-duct','Alveolar duct','This passage is distal to a respiratory bronchiole.','Its walls are formed largely by the openings of alveoli.','It leads toward alveolar sacs.','Alveolar ducts are elongated passages lined almost entirely by alveolar openings.')
add('alveolar-sac','Alveolar sac','Look at a terminal cluster of air spaces.','Several alveoli share a common distal chamber.','Use the collective sac name rather than the name of a single air pocket.','An alveolar sac is a group of alveoli opening into a common distal space.')
add('alveolus','Alveolus','This is one small air space at the end of the respiratory tree.','Its thin wall participates in gas exchange.','Use the singular form; the plural is alveoli.','An alveolus is a microscopic air space bounded by an epithelial wall closely associated with pulmonary capillaries.')
add('type-one-cell','Type I alveolar cell','Use the enlarged alveolar-wall inset.','This very thin squamous cell covers most of the alveolar surface.','It is the principal epithelial component of the air–blood barrier.','Type I pneumocytes provide a thin surface for gas diffusion; they are distinct from the cuboidal surfactant-secreting cells.',['Type I pneumocyte','Type 1 alveolar cell','Type 1 pneumocyte'])
add('type-two-cell','Type II alveolar cell','Use the enlarged alveolar-wall inset.','This plumper epithelial cell secretes pulmonary surfactant.','It also contributes to renewal of the alveolar epithelium.','Type II pneumocytes secrete surfactant and can proliferate after injury.',['Type II pneumocyte','Type 2 alveolar cell','Type 2 pneumocyte'])
add('alveolar-macrophage','Alveolar macrophage','This free or surface-associated cell is in an alveolar air space.','It phagocytoses inhaled particles and debris.','Its older name is a dust cell.','Alveolar macrophages patrol the air-facing alveolar surface and remove particles.',['Dust cell'])
add('pulmonary-capillary','Pulmonary capillary','The pin lies on a tiny vessel in the alveolar wall.','Red blood cells pass immediately adjacent to the gas-exchange surface.','Use the pulmonary adjective with the smallest vessel class.','Pulmonary capillaries form a network around alveoli. Gas crosses the respiratory membrane between air and blood.',['Alveolar capillary'])
add('respiratory-membrane','Respiratory membrane','This target is the thin air–blood interface.','It includes alveolar epithelium, associated basement membranes and capillary endothelium.','It is also called the blood–air barrier.','The respiratory membrane separates alveolar gas from capillary blood; the illustration exaggerates layer thickness for visibility.',['Blood air barrier','Air blood barrier','Alveolar capillary membrane'])
add('alveolar-pore','Alveolar pore','Look at a small opening in an alveolar wall.','It communicates between adjacent alveoli.','It is also called a pore of Kohn.','Alveolar pores are small interalveolar communications; they permit collateral airflow.',['Pore of Kohn'])
add('parietal-pleura','Parietal pleura','Use the enlarged chest-wall inset.','This serous layer lines the inner chest wall, diaphragm and mediastinum.','Its name means relating to a wall.','The parietal pleura lines the pleural compartment and reflects onto the lung at its root.')
add('visceral-pleura','Visceral pleura','Use the enlarged chest-wall inset.','This serous layer closely covers the lung and enters its fissures.','Its name means relating to an organ.','The visceral pleura is adherent to the lung surface; it is continuous with parietal pleura at the lung root.')
add('pleural-cavity','Pleural cavity','The pin lies between the two pleural layers.','Normally this is a potential space with a thin film of serous fluid.','It is exaggerated in the inset so it can be seen.','The pleural cavity lies between visceral and parietal pleura. The two sides are separate compartments.',['Pleural space'])
add('diaphragm','Diaphragm','This dome-shaped muscle forms the floor of the thorax.','Its thoracic surface is covered centrally by pericardial attachments and laterally by parietal pleura.','It is supplied primarily by the phrenic nerves, C3–C5.','The diaphragm separates thoracic and abdominal cavities and is the principal muscle of inspiration.')
add('costodiaphragmatic-recess','Costodiaphragmatic recess','Look near the inferior reflection of the pleura.','It lies where costal parietal pleura meets diaphragmatic pleura.','The lung expands into this recess during deep inspiration.','The costodiaphragmatic recess is a pleural potential space between the chest wall and diaphragm; its size depends on respiratory phase.',['Costophrenic recess'])
